93	// LoggingInterceptor logs Connect RPC requests with appropriate log levels.
94	//
95	// Log levels:
96	// - INFO: Successful requests and expected client errors (not found, permission denied, etc.)
97	// - ERROR: Server errors (internal, unavailable, etc.)
98	type LoggingInterceptor struct {
99		logStacktrace bool
100	}
101	
102	// NewLoggingInterceptor creates a new logging interceptor.
103	func NewLoggingInterceptor(logStacktrace bool) *LoggingInterceptor {
104		return &LoggingInterceptor{logStacktrace: logStacktrace}
105	}
106	
107	func (in *LoggingInterceptor) WrapUnary(next connect.UnaryFunc) connect.UnaryFunc {
108		return func(ctx context.Context, req connect.AnyRequest) (connect.AnyResponse, error) {
109			resp, err := next(ctx, req)
110			in.log(req.Spec().Procedure, err)
111			return resp, err
112		}
113	}
114	
115	func (*LoggingInterceptor) WrapStreamingClient(next connect.StreamingClientFunc) connect.StreamingClientFunc {
116		return next // No-op for server-side interceptor
117	}
118	
119	func (*LoggingInterceptor) WrapStreamingHandler(next connect.StreamingHandlerFunc) connect.StreamingHandlerFunc {
120		return next // Streaming not used in this service
121	}
122	
123	func (in *LoggingInterceptor) log(procedure string, err error) {
124		level, msg := in.classifyError(err)
125		attrs := []slog.Attr{slog.String("method", procedure)}
126		if err != nil {
127			attrs = append(attrs, slog.String("error", err.Error()))
128			if in.logStacktrace {
129				attrs = append(attrs, slog.String("stacktrace", fmt.Sprintf("%+v", err)))
130			}
131		}
132		slog.LogAttrs(context.Background(), level, msg, attrs...)
133	}
134	
135	func (*LoggingInterceptor) classifyError(err error) (slog.Level, string) {
136		if err == nil {
137			return slog.LevelInfo, "OK"
138		}
139	
140		var connectErr *connect.Error
141		if !pkgerrors.As(err, &connectErr) {
142			return slog.LevelError, "unknown error"
143		}
144	
145		// Client errors (expected, log at INFO)
146		switch connectErr.Code() {
147		case connect.CodeCanceled,
148			connect.CodeInvalidArgument,
149			connect.CodeNotFound,
150			connect.CodeAlreadyExists,
151			connect.CodePermissionDenied,
152			connect.CodeUnauthenticated,
153			connect.CodeResourceExhausted,
154			connect.CodeFailedPrecondition,
155			connect.CodeAborted,
156			connect.CodeOutOfRange:
157			return slog.LevelInfo, "client error"
158		default:
159			// Server errors
160			return slog.LevelError, "server error"
161		}
162	}
163	
164	// RecoveryInterceptor recovers from panics in Connect handlers and returns an internal error.
165	type RecoveryInterceptor struct {
166		logStacktrace bool
167	}
168	
169	// NewRecoveryInterceptor creates a new recovery interceptor.
170	func NewRecoveryInterceptor(logStacktrace bool) *RecoveryInterceptor {
171		return &RecoveryInterceptor{logStacktrace: logStacktrace}
172	}
173	
174	func (in *RecoveryInterceptor) WrapUnary(next connect.UnaryFunc) connect.UnaryFunc {
175		return func(ctx context.Context, req connect.AnyRequest) (resp connect.AnyResponse, err error) {
176			defer func() {
177				if r := recover(); r != nil {
178					in.logPanic(req.Spec().Procedure, r)
179					err = connect.NewError(connect.CodeInternal, pkgerrors.New("internal server error"))
180				}
181			}()
182			return next(ctx, req)
183		}
184	}
185	
186	func (*RecoveryInterceptor) WrapStreamingClient(next connect.StreamingClientFunc) connect.StreamingClientFunc {
187		return next
188	}
189	
190	func (*RecoveryInterceptor) WrapStreamingHandler(next connect.StreamingHandlerFunc) connect.StreamingHandlerFunc {
191		return next
192	}
193	
194	func (in *RecoveryInterceptor) logPanic(procedure string, panicValue any) {
195		attrs := []slog.Attr{
196			slog.String("method", procedure),
197			slog.Any("panic", panicValue),
198		}
199		if in.logStacktrace {
200			attrs = append(attrs, slog.String("stacktrace", string(debug.Stack())))
201		}
202		slog.LogAttrs(context.Background(), slog.LevelError, "panic recovered in Connect handler", attrs...)
203	}
