12	func TestMetadataInterceptorForwardsSecurityHeaders(t *testing.T) {
13		interceptor := NewMetadataInterceptor()
14		req := connect.NewRequest(&emptypb.Empty{})
15		req.Header().Set("Origin", "https://memos.example")
16		req.Header().Set("X-Forwarded-Proto", "https")
17		req.Header().Set("Forwarded", "for=203.0.113.1;proto=https")
18	
19		handler := interceptor.WrapUnary(func(ctx context.Context, _ connect.AnyRequest) (connect.AnyResponse, error) {
20			md, ok := metadata.FromIncomingContext(ctx)
21			if !ok {
22				t.Fatal("expected metadata in context")
23			}
24			if got := md.Get("origin"); len(got) != 1 || got[0] != "https://memos.example" {
25				t.Fatalf("unexpected origin metadata: %v", got)
26			}
27			if got := md.Get("x-forwarded-proto"); len(got) != 1 || got[0] != "https" {
28				t.Fatalf("unexpected x-forwarded-proto metadata: %v", got)
29			}
30			if got := md.Get("forwarded"); len(got) != 1 || got[0] != "for=203.0.113.1;proto=https" {
31				t.Fatalf("unexpected forwarded metadata: %v", got)
32			}
33			return connect.NewResponse(&emptypb.Empty{}), nil
34		})
35	
36		if _, err := handler(context.Background(), req); err != nil {
37			t.Fatalf("metadata interceptor returned error: %v", err)
38		}
39	}
