92		settings := make([]*storepb.InstanceSetting, 0, len(byKey))
93		for _, setting := range byKey {
94			settings = append(settings, setting)
95		}
96		slices.SortFunc(settings, func(a, b *storepb.InstanceSetting) int { return cmp.Compare(a.Key, b.Key) })
